-- 000057_seed_move_commands_third_wave.up.sql
-- M14-03e: 第三波 6 キャラの command 索引 move_commands の seed(非派生のみ)
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- 非派生技(is_derived=false)のみ搭載。token_key は numpad 正規化済み(internal/moveindex が一元管理)。
-- 索引は広く持つ(必殺技・空中技も搭載)＝段階2 スコープへの絞り込みは消費者側(CHANGE-069 §1.5-6)。
-- 既存マイグレは非改変(新規連番で追加)。FK 依存順 characters→moves→move_commands。

-- ===== m_bison (45 commands) =====
INSERT INTO move_commands (move_id, character_id, token_key)
SELECT m.id, m.character_id, v.token_key
FROM moves m
JOIN characters c ON c.id = m.character_id
CROSS JOIN (
        SELECT 'sa2_psycho_punisher' AS code, '214214K' AS token_key
  UNION ALL SELECT 'backfist_combo_heavy', '214HP'
  UNION ALL SELECT 'backfist_combo_light', '214LP'
  UNION ALL SELECT 'backfist_combo_medium', '214MP'
  UNION ALL SELECT 'backfist_combo_od', '214P+P'
  UNION ALL SELECT 'sa1_knee_press_nightmare', '236236K'
  UNION ALL SELECT 'sa3_unlimited_psycho_crusher', '236236P'
  UNION ALL SELECT 'ca_unlimited_psycho_crusher', '236236P'
  UNION ALL SELECT 'double_knee_press_heavy', '236HK'
  UNION ALL SELECT 'double_knee_press_od', '236K+K'
  UNION ALL SELECT 'double_knee_press_light', '236LK'
  UNION ALL SELECT 'double_knee_press_medium', '236MK'
  UNION ALL SELECT 'crouching_heavy_kick', '2HK'
  UNION ALL SELECT 'crouching_heavy_punch', '2HP'
  UNION ALL SELECT 'crouching_light_kick', '2LK'
  UNION ALL SELECT 'crouching_light_punch', '2LP'
  UNION ALL SELECT 'crouching_medium_kick', '2MK'
  UNION ALL SELECT 'crouching_medium_punch', '2MP'
  UNION ALL SELECT 'hover_kick', '3HK'
  UNION ALL SELECT 'evil_knee', '4HK'
  UNION ALL SELECT 'throw_back', '4LP+LK'
  UNION ALL SELECT 'throw_forward', '5/6LP+LK'
  UNION ALL SELECT 'psycho_hammer', '6HP'
  UNION ALL SELECT 'standing_heavy_kick', 'HK'
  UNION ALL SELECT 'jumping_heavy_kick', 'HK'
  UNION ALL SELECT 'standing_heavy_punch', 'HP'
  UNION ALL SELECT 'jumping_heavy_punch', 'HP'
  UNION ALL SELECT 'drive_impact', 'HP+HK'
  UNION ALL SELECT 'standing_light_kick', 'LK'
  UNION ALL SELECT 'jumping_light_kick', 'LK'
  UNION ALL SELECT 'standing_light_punch', 'LP'
  UNION ALL SELECT 'jumping_light_punch', 'LP'
  UNION ALL SELECT 'standing_medium_kick', 'MK'
  UNION ALL SELECT 'jumping_medium_kick', 'MK'
  UNION ALL SELECT 'standing_medium_punch', 'MP'
  UNION ALL SELECT 'jumping_medium_punch', 'MP'
  UNION ALL SELECT 'drive_parry', 'MP+MK'
  UNION ALL SELECT 'shadow_rise_heavy', '[2]8HK'
  UNION ALL SELECT 'shadow_rise_od', '[2]8K+K'
  UNION ALL SELECT 'shadow_rise_light', '[2]8LK'
  UNION ALL SELECT 'shadow_rise_medium', '[2]8MK'
  UNION ALL SELECT 'psycho_crusher_attack_heavy', '[4]6HP'
  UNION ALL SELECT 'psycho_crusher_attack_light', '[4]6LP'
  UNION ALL SELECT 'psycho_crusher_attack_medium', '[4]6MP'
  UNION ALL SELECT 'psycho_crusher_attack_od', '[4]6P+P'
) AS v
WHERE c.code = 'm_bison' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6') AND m.code = v.code;

